private void nine(Mat image, int t1, int t2) {
    if (image != null) {
        // Проверка правильности введенных значений порогов
        if (t2 <= t1) {
            JOptionPane.showMessageDialog(null, "Значение порога 2 должно быть больше порога 1");
            return;
        }

        final int TEETH = (int) ImageReader.userInput("Введите количество зубьев:", 2, 10); // Запрос значения количества зубьев
        final int index = 0; // или любое другое значение

        Mat resultImage = new Mat(image.size(), image.type());
        for (int i = 0; i < image.rows(); i++) {
            for (int j = 0; j < image.cols(); j++) {
                double[] data = image.get(i, j);

                for (int p = 0; p < image.channels(); p++) {
                    int cell = (int) (255 * (data[p] - (double) t1) / ((double) t2 - (double) t1));
                    if ((double) t2 >= data[p] && data[p] >= (double) t1) {
                        cell = (cell * 255) / (255 / TEETH);
                        if (cell <= index) {
                            data[p] = 0;
                        } else {
                            data[p] = 255;
                        }
                    }
                }

                resultImage.put(i, j, data);
            }
        }
        HighGui.imshow("Zigzag Contrast", resultImage);
        HighGui.waitKey();
    }
}
